model.component("comp1").physics("vef").feature("fp1").set("Constitutiverelation", "Viscoelastic");
model.component("comp1").physics("vef").feature("fp1").set("MaterialModelViscoelastic", "OldroydB");
// GUI: branch table row 1: viscosity 1[Pa*s], relaxation time 0.1[s]; add row 2 for a second mode

model.component("comp1").physics("vef").feature("fp1").set("MaterialModelViscoelastic", "OldroydB");
// Weissenberg number Wi = lambda*U/L; ramp lambda with a Parametric Sweep for high Wi
